input_fifo_3: entity work.axis_data_fifo_0
     port map (
      almost_full => NLW_input_fifo_3_almost_full_UNCONNECTED,
      axis_wr_data_count(31 downto 0) => NLW_input_fifo_3_axis_wr_data_count_UNCONNECTED(31 downto 0),
      m_axis_tdata(31 downto 0) => \fifo_data_out[3]\(31 downto 0),
      m_axis_tlast => input_fifo_3_n_34,
      m_axis_tready => fifo_in_ready(3),
      m_axis_tvalid => input_fifo_3_n_1,
      s_axis_aclk => clk_IBUF_BUFG,
      s_axis_aresetn => reset_fifos_IBUF,
      s_axis_tdata(31 downto 0) => data_in_IBUF(31 downto 0),
      s_axis_tlast => end_of_frame_IBUF,
      s_axis_tready => NLW_input_fifo_3_s_axis_tready_UNCONNECTED,
      s_axis_tvalid => data_in_valid_IBUF
    );
last_frame_OBUF_inst: unisim.vcomponents.OBUFT
     port map (
      I => '0',
      O => last_frame,
      T => '1'
    );
ldpc_core_clk_IBUF_inst: unisim.vcomponents.IBUF
     port map (
      I => ldpc_core_clk,
      O => ldpc_core_clk_IBUF
    );
reset_IBUF_inst: unisim.vcomponents.IBUF
     port map (
      I => reset,
      O => reset_IBUF
    );
reset_fifos_IBUF_inst: unisim.vcomponents.IBUF
     port map (
      I => reset_fifos,
      O => reset_fifos_IBUF
    );
end STRUCTURE;
